"검진 결과지에 빨간 글씨가 늘어난 걸 보고, 재검사 날짜를 달력에 큼직한 동그라미로 쳐 두었다":"เห็นตัวอักษรสีแดงในผลตรวจเพิ่มขึ้น เลยวงวันตรวจซ้ำบนปฏิทินด้วยวงกลมใหญ่ ๆ",
