"사장님은 그때 새벽에 졸던 나를 기억했다. 소개받은 자리에서 첫 달부터 일했다":"เจ้าของร้านจำได้ว่าเราเคยหลับตอนเช้ามืด ที่ที่ได้รับการแนะนำให้ไป ก็ได้ทำงานตั้งแต่เดือนแรก",
