"사진관에서 가장 단정한 옷을 입고 사진을 찍은 날, {0}이/가 뒤에서 옷깃을 한 번 더 폈다":"วันที่ใส่เสื้อผ้าที่เรียบร้อยที่สุดไปถ่ายรูปที่ร้านถ่ายภาพ {0} ช่วยจัดปกเสื้อให้อีกครั้งจากข้างหลัง",
"사진을 정리한다":"จัดระเบียบรูปถ่าย",
"사진을 찍어 주고 박수를 쳤다. 모두가 돌아간 뒤 남은 컵을 치웠다":"ถ่ายรูปให้แล้วปรบมือ พอทุกคนกลับกันไปก็เก็บถ้วยที่เหลือ",
"사촌 형이 입던 옷을 물려 입었는데 소매가 길어서 두 번 접어 올려야 손이 나왔고 그래도 따뜻해서 좋았다":"ใส่เสื้อที่ลูกพี่ลูกน้องชายเคยใส่ต่อ แขนยาวจนต้องพับขึ้นสองทบมือถึงโผล่ออกมา แต่ก็อุ่นดีเลยชอบ",
