"살아온 이야기를 낡은 공책에 연필로 한 줄씩 적다가, 끝내 기억나지 않는 날짜는 빈칸으로 남겨 두었다":"เขียนเรื่องราวที่ผ่านมาลงสมุดเก่าด้วยดินสอทีละบรรทัด แล้ววันที่นึกไม่ออกในที่สุดก็ปล่อยเป็นช่องว่าง",
"삶 돌아보기":"ย้อนมองชีวิต",
"상담실을 나와 말없이 걸었다":"ออกจากห้องให้คำปรึกษาแล้วเดินไปเงียบ ๆ",
"상담을 받는다":"เข้ารับคำปรึกษา",
"상자에 책상 물건을 담아 돌아오는 길, 버스 창에 비친 내 얼굴이 낯설어 한참 고개를 돌렸다":"ระหว่างทางกลับบ้านพร้อมกล่องของจากโต๊ะทำงาน ใบหน้าตัวเองที่สะท้อนในหน้าต่างรถเมล์ดูแปลกตา จนต้องหันหน้าหนีอยู่นาน",
"상자에 책상 물건을 담아 풀 죽은 채 돌아온 날, {0}이/가 아무것도 묻지 않고 따뜻한 밥부터 차렸다":"วันที่กลับบ้านอย่างห่อเหี่ยวพร้อมกล่องของจากโต๊ะทำงาน {0}ไม่ถามอะไรสักคำ แต่จัดข้าวอุ่น ๆ มาให้ก่อน",
"상장을 내밀자 {0}이/가 두 번이나 읽어 보고는 말없이 벽 한가운데에 붙여 주었다":"พอยื่นเกียรติบัตรให้ {0}อ่านซ้ำสองรอบ แล้วเอาไปติดกลางผนังให้โดยไม่พูดอะไร",
"새 게임기 하나를 {0}와/과 나눠 써야 한다":"ต้องแบ่งเครื่องเล่นเกมเครื่องใหม่เครื่องเดียวกับ{0}",
