"새 일을 찾는다":"หางานใหม่",
"새 일터에서 어른들이 요령을 아낌없이 하나하나 가르쳐 주어, 석 달이 지나자 손이 저절로 움직였다":"ที่ทำงานใหม่ รุ่นพี่สอนเคล็ดลับให้ทีละอย่างไม่ปิดบัง พอผ่านไปสามเดือนมือก็ขยับเองได้เอง",
"새 직장 동료들이 이름을 외워 부르기 시작했고, 점심 줄에서 자연스럽게 내 옆자리가 비워졌다":"เพื่อนร่วมงานใหม่เริ่มจำชื่อแล้วเรียกกัน ในแถวซื้ออาหารกลางวัน ที่ข้างตัวก็มีคนเว้นที่ไว้ให้อย่างเป็นธรรมชาติ",
"새 직장 면접관이 어릴 때 지갑 주인 같다":"ผู้สัมภาษณ์งานที่ใหม่ ดูเหมือนเจ้าของกระเป๋าสตางค์ที่เจอตอนเด็ก",
"새 학교 아이들이 내 말씨를 따라 한다":"เด็กในโรงเรียนใหม่เลียนสำเนียงพูดของฉัน",
"새로 들어온 기계가 낯설어 설명서를 몇 번이나 펴 보다, 젊은 일꾼에게 머쓱하게 물었다":"เครื่องจักรที่เพิ่งเข้ามาดูแปลกตา เปิดคู่มืออ่านอยู่หลายรอบ ก่อนจะเขินอายถามคนงานหนุ่ม",
"새로 들어온 후배에게 손에 익은 요령을 알려 주자, 한 달 만에 나보다 빨라졌다":"พอสอนเคล็ดลับที่ชำนาญให้รุ่นน้องที่เพิ่งเข้ามา ภายในเดือนเดียวเขาก็ทำเร็วกว่าฉัน",
