"새벽 세 시면 눈이 떠져, 천장 무늬를 세다 날이 밝았다":"ตีสามก็ลืมตาตื่น นับลายบนเพดานจนฟ้าสว่าง",
"새벽 장터에서 곡식 자루를 지고 상인들 사이를 오가며 하루 품삯을 받았다":"ตลาดเช้ามืด แบกกระสอบธัญพืชเดินไปมาระหว่างพ่อค้าแม่ค้า แล้วรับค่าแรงรายวัน",
"새벽 첫 버스에 올라 창에 이마를 대고 마을 불빛이 점점 멀어지는 것을 끝까지 보았다":"ขึ้นรถเมล์คันแรกตอนเช้ามืด เอาหน้าผากพิงหน้าต่าง แล้วมองแสงไฟของหมู่บ้านที่ค่อย ๆ ห่างไปจนสุดทาง",
"새벽마다 공원을 한 바퀴 돌며 늘 같은 자리에서 체조하는 얼굴들과 눈인사를 나누는 게 하루 첫 일과였다":"ทุกเช้ามืดเดินรอบสวนสาธารณะหนึ่งรอบ ทักทายด้วยสายตากับหน้าคุ้นเคยที่ออกกำลังกายอยู่ที่เดิมเสมอ นั่นคือกิจวัตรแรกของวัน",
"새벽마다 기침이 멎지 않아 {0}이/가 등을 쓸어 주었고, 그제야 이번 주말엔 병원에 가 보기로 마음먹었다":"ทุกเช้ามืดไอไม่หยุด {0}ลูบหลังให้ ตอนนั้นจึงตัดสินใจว่าสุดสัปดาห์นี้จะไปหาหมอ",
"새벽마다 마당의 수탉이 울면 이불을 뒤집어쓰고 한 번만 더 자겠다고 빌었지만 이내 이불을 걷어차고 마당으로 나갔다":"ทุกเช้าพอไก่ตัวผู้ในลานบ้านขัน ก็ซุกผ้าห่มอ้อนวอนขอนอนอีกแค่ครั้งเดียว แต่สุดท้ายก็เตะผ้าห่มออกแล้ววิ่งไปที่ลานบ้าน",
"새참 때 옆자리 동료가 건넨 시원한 물 한 잔에 말문이 트여, 그날부터 서로 일을 챙기게 되었다":"น้ำเย็น ๆ หนึ่งแก้วที่เพื่อนร่วมงานข้าง ๆ ยื่นให้ตอนพักกลางงานทำให้เริ่มคุยกันได้ ตั้งแต่วันนั้นก็คอยดูแลงานกันและกัน",
