"새해 첫날 아침 온 식구가 둘러앉아 떡이 든 국을 먹고, 어른들이 건네는 작은 봉투를 두 손으로 받았다":"เช้าวันปีใหม่ทั้งบ้านนั่งล้อมวงกินซุปใส่ต๊อก แล้วรับซองเล็ก ๆ จากผู้ใหญ่ด้วยสองมือ",
