"생일 저녁, 불을 끄자 {0}이/가 촛불 여덟 개가 꽂힌 케이크를 내오고 온 식구가 노래를 불러 주었다":"เย็นวันเกิด พอดับไฟ {0}ก็ยกเค้กที่ปักเทียนแปดเล่มออกมา แล้วทั้งบ้านก็ร้องเพลงให้",
