"생일에 {0}에게 새 휴대폰을 받아 포장을 뜯고 이불 속에서 밤새 화면을 켰다 껐다 하며 설정을 만졌다":"วันเกิดได้รับมือถือเครื่องใหม่จาก{0} แกะกล่องแล้วเปิดปิดหน้าจอปรับตั้งค่าอยู่ในผ้าห่มทั้งคืน",
