"서랍 속 낡은 연필을 꺼내 {0}의 옆에 앉아, 같은 종이에 나란히 고양이를 그렸다":"หยิบดินสอเก่าในลิ้นชักมานั่งข้าง ๆ {0} แล้ววาดแมวเคียงกันบนกระดาษแผ่นเดียวกัน",
"서랍 속 낡은 연필을 꺼내 오랜만에 창밖 풍경을 스케치하다가, 해가 지는 줄도 모른 채 종이를 가득 채웠다":"หยิบดินสอเก่าในลิ้นชักมาสเก็ตช์ทิวทัศน์นอกหน้าต่างเป็นครั้งแรกในรอบนาน วาดจนเต็มกระดาษโดยไม่รู้ว่าพระอาทิตย์ตกแล้ว",
