"서랍 속 물건에 이름표를 붙이며 누구에게 건넬지 하나씩 헤아려 보았다":"ติดป้ายชื่อบนของในลิ้นชัก แล้วไล่นึกทีละชิ้นว่าจะยื่นให้ใคร",
"서랍 안쪽에서 낡은 저금통이 나왔다":"เจอกระปุกออมสินเก่าอยู่ลึกในลิ้นชัก",
"서랍에 감춘다":"ซ่อนไว้ในลิ้นชัก",
"서랍에서 {0}와/과 둘이 찍은 사진이 나와, 뒷면에 적힌 장난스런 글씨를 소리 내어 읽었다":"เจอรูปถ่ายคู่กับ{0}ในลิ้นชัก แล้วอ่านออกเสียงข้อความขี้เล่นที่เขียนไว้ด้านหลัง",
"서랍을 열어 볼 때마다 기다렸지만 답장은 끝내 오지 않았고 졸업식 날까지 그 서랍 쪽을 쳐다보지 못했다":"ทุกครั้งที่เปิดลิ้นชักก็รอคอย แต่คำตอบก็ไม่เคยมาถึง จนถึงวันรับปริญญาก็ไม่กล้ามองไปทางลิ้นชักนั้นอีก",
"서로 말을 하기 시작했다":"เริ่มพูดคุยกัน",
"서로 먼저 전화하지 않은 채 어색한 침묵 속에서 계절이 한 번 바뀌었다":"ต่างคนต่างไม่โทรหาก่อน ท่ามกลางความเงียบที่อึดอัด ฤดูกาลก็เปลี่ยนไปหนึ่งรอบ",
"서로 휴대폰을 내밀어 번호를 눌러 주고 이십 년 전처럼 어색하게 마주 보며 웃었다":"ยื่นมือถือให้กันกดเบอร์ให้ แล้วมองหน้ากันอย่างเก้อเขินเหมือนเมื่อยี่สิบปีก่อนพลางหัวเราะ",
"서류만 낸다":"ส่งแค่เอกสาร",
"석 달 걸린 프로젝트가 끝나던 날, 팀원들과 불 꺼진 회의실에 남아 컵라면 하나씩으로 소리 없이 축하했다":"วันที่โปรเจกต์สามเดือนจบลง ฉันอยู่ในห้องประชุมที่ปิดไฟกับทีม ฉลองเงียบ ๆ ด้วยบะหมี่กึ่งสำเร็จรูปถ้วยละคน",
"선물을 산다":"ซื้อของขวัญ",
"선생님께 말한다":"บอกครู",
