"선생님이 앞에 나가 발표할 사람을 찾는다":"ครูกำลังหาคนออกไปพูดหน้าชั้น",
"선수에 도전한다":"ท้าชิงเป็นนักกีฬา",
"선천성 질환":"โรคที่เป็นมาแต่กำเนิด",
"설거지를 하다 문득 손등이 {0}의 손을 닮았다는 걸 알고, 물을 잠그고 한참 내려다봤다":"ล้างจานอยู่ก็สังเกตเห็นว่าหลังมือเหมือนมือของ{0} จึงปิดน้ำแล้วมองลงไปอยู่นาน",
