"설거지하는 {0}의 손등이 거칠게 튼 것을 처음 발견하고 말없이 옆에 서서 행주를 집어 들었고 그날 처음으로 둘이 나란히 그릇을 닦았다":"เห็นหลังมือของ{0}ที่ล้างจานแตกหยาบเป็นครั้งแรก ก็ไปยืนข้าง ๆ เงียบ ๆ แล้วหยิบผ้าเช็ดจาน วันนั้นเป็นครั้งแรกที่สองคนยืนล้างจานเคียงกัน",
"설사병":"ท้องร่วง",
"설정":"ตั้งค่า",
"성과금이 들어온 날, 가장 먼저 {0}에게 따뜻한 겉옷을 사 보냈고 전화에서 한참 사양하는 목소리가 들렸다":"วันที่เงินโบนัสเข้า สิ่งแรกที่ทำคือซื้อเสื้อคลุมอุ่น ๆ ส่งให้{0} ทางโทรศัพท์ได้ยินเสียงปฏิเสธอยู่นาน",
"성과금이 들어온 날, 오래 눈여겨본 가게에서 새 신발을 사 신고 집까지 천천히 걸었다":"วันที่เงินโบนัสเข้า ซื้อรองเท้าคู่ใหม่จากร้านที่เล็งไว้นาน ใส่แล้วเดินกลับบ้านช้า ๆ",
"성적표 뒷장에 다음 시험 계획을 적어 함께 내밀었다":"เขียนแผนสอบครั้งหน้าไว้หลังใบรายงานผล แล้วยื่นให้พร้อมกัน",
"성적표를 내밀자 {0}은/는 점수 대신 내 눈치부터 보았다":"พอยื่นใบรายงานผล {0}ไม่ได้ดูคะแนน แต่ดูสีหน้าของฉันก่อน",
"성탄 저녁 식구들이 길게 이어 붙인 식탁에 앉아 칠면조 다리를 서로 양보하다가 결국 반으로 나눠 웃으며 먹었다":"เย็นวันคริสต์มาส ทั้งบ้านนั่งที่โต๊ะอาหารที่ต่อกันยาว ๆ ต่างยกน่องไก่งวงให้กัน สุดท้ายก็แบ่งครึ่งแล้วกินไปหัวเราะไป",
"성탄 전야 사촌들이 한 집에 모여 졸린 눈을 비비면서도 밤늦도록 식탁을 둘러싸고 떠들었다":"คืนก่อนคริสต์มาส ลูกพี่ลูกน้องมารวมกันที่บ้านหลังเดียว ขยี้ตาง่วง ๆ แต่ก็นั่งล้อมโต๊ะคุยกันดึกดื่น",
