"세상에 남기는 말":"คำที่ทิ้งไว้ให้โลก",
"소개받은 사람과 카페 구석 자리에 마주 앉아, 식어 가는 커피를 앞에 두고 두 시간을 쉬지 않고 이야기했다":"นั่งตรงข้ามกับคนที่มีคนแนะนำให้ที่มุมร้านกาแฟ มีกาแฟที่เย็นลงทุกที แล้วคุยกันไม่หยุดสองชั่วโมง",
"소나기가 그친 뒤 노란 장화를 신고 빗물 웅덩이마다 들어가 물이 사방으로 튀도록 첨벙대다가 양말까지 흠뻑 젖어 신이 났다":"หลังฝนซา ใส่รองเท้าบูทสีเหลืองลงไปย่ำทุกแอ่งน้ำจนน้ำกระเซ็นไปทั่ว ถุงเท้าเปียกโชกก็ยังสนุก",
