"손가락이 건반 위를 기억해 냈다. 노래가 끝나자 박수가 길게 이어졌다":"นิ้วจำตำแหน่งบนคีย์บอร์ดได้ขึ้นมา พอเพลงจบ เสียงปรบมือก็ดังยาวนาน",
