"손만 잡는다":"แค่จับมือ",
"손수 접어 만든 종이배를 비 온 뒤 도랑물에 띄우고 하수구 앞까지 끝까지 따라 달렸다":"พับเรือกระดาษด้วยมือ แล้วลอยลงในร่องน้ำหลังฝนตก วิ่งตามไปจนถึงปากท่อ",
"손수 터를 닦고 기둥을 세워 올린 집에 처음으로 불을 땠고, 굴뚝에서 연기가 올랐다":"ก่อไฟครั้งแรกในบ้านที่ลงมือปรับพื้นที่ตั้งเสาขึ้นมาเอง ควันลอยขึ้นจากปล่องไฟ",
