"손주 숙제를 돋보기로 읽어 주다가, 모르는 문제는 같이 사전을 찾아보았다":"ใช้แว่นขยายอ่านการบ้านของหลานให้ฟัง ข้อที่ไม่รู้ก็เปิดพจนานุกรมหาด้วยกัน",
"손주가 {0}을/를 거치지 않고 나를 직접 불러 달려와, 두 팔을 있는 대로 벌렸다":"หลานไม่ผ่าน{0} แต่เรียกฉันตรง ๆ แล้ววิ่งมา กางแขนสองข้างออกสุด",
"손주가 나를 직접 부르며 달려와, 두 팔을 있는 대로 벌렸다":"หลานเรียกฉันตรง ๆ แล้ววิ่งมา กางแขนสองข้างออกสุด",
"손주들이 와서 집 안이 시끌벅적해졌고, 오래 닫아 두었던 건넌방 문이 하루 종일 활짝 열려 있었다":"พอหลาน ๆ มา บ้านก็คึกคักเสียงดัง ประตูห้องฝั่งตรงข้ามที่ปิดไว้นานเปิดกว้างอยู่ทั้งวัน",
"손주를 무릎에 앉히고, 어릴 적 할머니가 들려주던 옛이야기를 목소리까지 흉내 내 한 편 통째로 들려줬다":"อุ้มหลานนั่งตัก แล้วเล่านิทานเก่าที่ยายเคยเล่าให้ฟังตอนเด็กทั้งเรื่อง เลียนเสียงด้วย",
"송별회에서 받은 꽃다발을 안고 버스로 퇴근하며, 내일부터는 아침 알람을 맞추지 않아도 된다는 게 낯설었다":"กอดช่อดอกไม้จากงานเลี้ยงอำลา นั่งรถเมล์กลับบ้าน รู้สึกแปลกที่ตั้งแต่พรุ่งนี้ไม่ต้องตั้งนาฬิกาปลุกตอนเช้าแล้ว",
"수단":"ซูดาน",
