"수술 자국 위로 털이 다시 자란 어느 저녁, {0}이/가 계단을 나보다 먼저 뛰어 올라갔다":"ค่ำวันหนึ่ง ขนบริเวณรอยแผลผ่าตัดงอกขึ้นมาใหม่ {0}วิ่งขึ้นบันไดไปก่อนฉัน",
