"수업을 빼먹고 혼자 담을 넘어 오락실과 간식 가게를 쏘다니다 해 질 녘에야 슬금슬금 집으로 돌아왔다":"โดดเรียนแล้วปีนกำแพงไปเที่ยวร้านเกมและร้านขนมคนเดียว เดินเตร็ดเตร่จนพลบค่ำถึงค่อย ๆ แอบกลับบ้าน",
