"수확 잔치 마당에서 북소리에 맞춰 어른들과 어깨를 맞대고 발을 굴러 흙먼지를 일으키며 밤이 깊어 가는 줄 몰랐다":"ในลานเทศกาลเก็บเกี่ยว ตามเสียงกลอง เบียดไหล่กับผู้ใหญ่แล้วกระทืบเท้าจนฝุ่นดินฟุ้ง ไม่รู้ตัวเลยว่าคืนล่วงไปลึกแล้ว",
