"식구가 하나둘 도시로 떠난 집에서 밥상을 혼자 차려, 반찬 두 가지로 저녁을 때웠다":"ในบ้านที่คนในครอบครัวทยอยไปอยู่เมือง จัดสำรับคนเดียว มื้อเย็นกินกับข้าวแค่สองอย่าง",
