"점심시간에 도시락이 없어 아이들이 밥 먹는 동안 운동장 수돗가에서 물만 마시고 배를 눌렀다":"ตอนพักเที่ยงไม่มีข้าวกล่อง ระหว่างที่เด็ก ๆ กินข้าว ฉันดื่มแต่น้ำที่ก๊อกในสนามแล้วกดท้องไว้",
