"접어 둔다":"พับเก็บไว้",
"접은 쪽지를 사물함에 넣었다. 다음 날 답장 쪽지가 책상 서랍에 있었다":"ใส่กระดาษโน้ตที่พับไว้ลงล็อกเกอร์ วันรุ่งขึ้นมีโน้ตตอบอยู่ในลิ้นชักโต๊ะ",
"정밀검진을 받는다":"ตรวจสุขภาพละเอียด",
"정비사":"ช่างซ่อม",
