"정전된 밤, {0}이/가 켠 촛불 아래서 식구 모두 손전등을 턱 밑에 대고 무서운 이야기를 하다 서로 놀라 웃었다":"คืนไฟดับ ใต้แสงเทียนที่{0}จุด ทั้งบ้านเอาไฟฉายส่องใต้คางเล่าเรื่องผี แล้วตกใจกันเองจนหัวเราะ",
"정중히 사양한다":"ปฏิเสธอย่างสุภาพ",
