"졸업 파티에서 친구가 술잔을 내민다":"ในงานเลี้ยงรับปริญญา เพื่อนยื่นแก้วเหล้ามาให้",
"졸업했다. 무슨 일을 할까":"เรียนจบแล้ว จะทำงานอะไรดี",
