"종이 치자마자 뛰어가 해 질 녘 밭머리에 닿았다. 반 고랑은 함께 맸다":"พอระฆังดังก็วิ่งไปถึงหัวไร่ตอนพลบค่ำ ช่วยกันถอนหญ้าครึ่งแปลง",
"좋아하는 아이가 생겼다. 말을 걸 수 있는 날은 오늘뿐이다":"มีคนที่ชอบแล้ว วันนี้เป็นวันเดียวที่จะเข้าไปทักได้",
"좋아하는 아이에게 마음을 말할까":"จะบอกความในใจกับคนที่ชอบดีไหม",
"좋은 요양 시설을 알아봤다":"ลองหาสถานดูแลผู้สูงอายุที่ดี",
