"주말마다 집이 시끌벅적했다":"ทุกสุดสัปดาห์ในบ้านคึกคักเสียงดัง",
"주말마다 합주실에서 보냈다":"ใช้ทุกสุดสัปดาห์อยู่ในห้องซ้อมดนตรี",
"주말마다 혼자 사는 어르신 집을 돌며 연탄을 날라 쌓고, 따뜻한 물 한 잔 얻어 마시며 안부를 물었다":"ทุกสุดสัปดาห์ไปบ้านผู้เฒ่าที่อยู่คนเดียว ขนถ่านอัดก้อนมากองซ้อน ขอน้ำอุ่นดื่มแก้วหนึ่งพลางถามสารทุกข์สุกดิบ",
"주말에 {0}이/가 빨랫감을 한 보따리 들고 와서, 밥은 먹고 가라며 붙잡는 척했다":"วันหยุดสุดสัปดาห์ {0}หอบผ้าที่ต้องซักมาเต็มห่อ แล้วแกล้งรั้งไว้ให้กินข้าวก่อนกลับ",
"주말에 가는 작은 집의 열쇠를 받아 {0}과/와 함께 창문을 활짝 열고 묵은 먼지를 털어 냈다":"ได้รับกุญแจบ้านหลังเล็กที่ไปวันหยุดสุดสัปดาห์ เปิดหน้าต่างให้กว้างกับ{0} แล้วปัดฝุ่นเก่าออก",
"주말에 가는 작은 집의 열쇠를 받아 혼자 창문을 활짝 열고 묵은 먼지를 털어 낸 뒤 마루에 누웠다":"ได้รับกุญแจบ้านหลังเล็กที่ไปวันหยุดสุดสัปดาห์ เปิดหน้าต่างให้กว้างคนเดียว ปัดฝุ่นเก่าออกแล้วนอนลงบนระเบียง",
