"중고 가게에서 산 휴대폰 화면이 켜지자, 저장된 첫 번호를 한참 쳐다보다 가족에게 전화를 걸었다":"พอหน้าจอมือถือที่ซื้อจากร้านมือสองติด จ้องเบอร์แรกที่บันทึกไว้อยู่นาน แล้วโทรหาครอบครัว",
"중국":"จีน",
"중앙아프리카공화국":"สาธารณรัฐแอฟริกากลาง",
