"지갑을 열 때마다 열 살 때 주운 지갑 속 낯선 얼굴이 떠올랐다. 그 돈은 오래전에 다 써 버렸다":"ทุกครั้งที่เปิดกระเป๋าสตางค์ ก็นึกถึงใบหน้าแปลกตาในกระเป๋าที่เก็บได้ตอนอายุสิบขวบ เงินนั้นใช้หมดไปนานแล้ว",
"지구에서 70명 중 1명 넘게 고향을 떠나 쫓겨났다":"บนโลก ผู้คนมากกว่า 1 ใน 70 คนต้องพลัดถิ่นจากบ้านเกิด",
"지금 {0}명이 살고 있다":"ตอนนี้มี{0}คนมีชีวิตอยู่",
