"집 뒤편 헛간을 치워 내 방으로 쓰기로 하고, 낡은 이불을 깔고 첫날 밤 문고리를 두 번 확인했다":"เก็บกวาดยุ้งหลังบ้านเป็นห้องของตัวเอง ปูผ้าห่มเก่า และคืนแรกตรวจลูกบิดประตูสองรอบ",
"집 앞 골목에 서서 큰 가방을 메고 떠나는 친구의 뒷모습을 모퉁이를 돌 때까지 바라보았다":"ยืนในซอยหน้าบ้าน มองหลังของเพื่อนที่สะพายกระเป๋าใบใหญ่จากไป จนเลี้ยวพ้นหัวมุม",
