"집이 허전하다. 강아지가 생각난다":"บ้านเงียบเหงา คิดถึงลูกสุนัข",
"집주인과 마주 앉아 계약 기간을 한 번 더 늘려 쓰고 비 오는 골목을 돌아왔다":"นั่งตรงข้ามกับเจ้าของบ้าน ต่อสัญญาเช่าอีกครั้ง แล้วเดินกลับมาในซอยท่ามกลางสายฝน",
