"짝꿍이 반 아이들에게 놀림당하고 있다":"เพื่อนร่วมโต๊ะถูกเพื่อนในห้องล้อ",
"짝꿍이 책상 밑으로 쪽지를 밀었다. 「고마워」 두 글자만 삐뚤빼뚤 적혀 있었다":"เพื่อนร่วมโต๊ะส่งกระดาษโน้ตใต้โต๊ะมา เขียนเอียง ๆ ไว้แค่สองคำว่า「ขอบใจ」",
"짝에게 미룬다":"ผลักให้เพื่อนร่วมโต๊ะ",
