"쩍쩍 갈라진 밭 앞에 혼자 서서, 다음 철은 뭘 먹고 버틸지 한참을 말없이 따져 보았다":"ยืนคนเดียวหน้าไร่ที่แตกระแหง คิดอยู่นานโดยไม่พูดว่าฤดูหน้าจะอยู่รอดด้วยอะไร",
