"창밖으로 처음 눈이 내리는 걸 보고 맨발로 문밖까지 뛰어나가 두 팔을 벌리고 소리를 질렀다":"เห็นหิมะตกเป็นครั้งแรกนอกหน้าต่าง วิ่งเท้าเปล่าออกไปนอกประตู กางแขนสองข้างแล้วตะโกน",
