"책상 모서리만 보며 숨을 죽였다. 다른 아이가 걸려 가슴이 쓸어내려졌다":"มองแต่มุมโต๊ะ กลั้นหายใจ เด็กคนอื่นถูกเรียกแทน จึงโล่งอก",
