"처마 끝에 맺힌 물방울이 떨어지는 걸 한 시간 세었다":"นั่งนับหยดน้ำที่ปลายชายคาร่วงลงมาเป็นเวลาหนึ่งชั่วโมง",
"처마 밑에서 기다린다":"รออยู่ใต้ชายคา",
"처음 먹어 본 묽은 쌀미음을 혀로 몇 번 밀어내다가 결국 한 숟가락을 꿀꺽 삼켰다":"ข้าวต้มเหลว ๆ ที่กินครั้งแรก ใช้ลิ้นดันออกหลายรอบ สุดท้ายก็กลืนไปหนึ่งช้อน",
"처음 먹어 본 묽은 옥수수죽이 싱거운지 입을 오물거리며 한참 고개를 갸웃거렸다":"โจ๊กข้าวโพดเหลว ๆ ที่กินครั้งแรก รสจืดไปหรือเปล่า จึงเคี้ยวปากหมุบหมิบเอียงคออยู่นาน",
"처음 먹어 본 으깬 감자를 손으로 헤집다가 얼굴 전체에 묻히고도 신이 나서 웃었다":"เจอมันบดที่กินครั้งแรก ใช้มือเขี่ยจนเปื้อนทั้งหน้า แต่ก็ยังหัวเราะอย่างสนุก",
