"처음으로 동전 몇 닢이 내 몫으로 생겼다":"เป็นครั้งแรกที่มีเหรียญไม่กี่เหรียญเป็นส่วนของตัวเอง",
"처음으로 용돈을 내 손으로 받았다":"เป็นครั้งแรกที่รับค่าขนมด้วยมือตัวเอง",
"천둥이 치는 밤 {0}의 이불 속으로 파고들어 귀를 막고 눈을 꼭 감은 채 번개가 지나가길 기다렸다":"คืนฟ้าร้อง มุดเข้าไปในผ้าห่มของ{0} ปิดหู หลับตาแน่น รอให้ฟ้าแลบผ่านไป",
"천변을 청소한다":"ทำความสะอาดริมคลอง",
"천장에서 비가 새는 자리에 양동이를 놓다가, 이웃에게 사다리를 빌려 직접 올라가 방수 천을 덧댔다":"ตอนวางถังรองตรงที่ฝนรั่วจากเพดาน ก็ยืมบันไดจากเพื่อนบ้านปีนขึ้นไปเอง แล้วแปะผ้ากันน้ำเพิ่ม",
