"첫 발표에서 말씨가 튀어 웃음이 터졌지만 끝까지 내 말로 마쳤다. 박수는 그 뒤에 더 컸다":"ในการพูดครั้งแรก สำเนียงหลุดจนมีคนหัวเราะ แต่ก็จบด้วยภาษาของตัวเองจนสุด เสียงปรบมือหลังจากนั้นดังกว่าเดิม",
"첫 월급 봉투를 뜯지도 않고 {0}의 손에 쥐여 드렸고, 둘이 시장 국숫집에서 국수 한 그릇씩을 비웠다":"ยื่นซองเงินเดือนแรกให้{0}โดยไม่ฉีก แล้วสองคนก็กินก๋วยเตี๋ยวที่ร้านในตลาดจนหมดชามละชาม",
"첫 월급날, 일터 문 앞에서 {0}의 작업복 뒤를 졸졸 따르던 어린 나의 발소리가 불쑥 들렸다":"วันเงินเดือนแรก หน้าประตูที่ทำงาน ได้ยินเสียงฝีเท้าของฉันตอนเด็กที่เดินตามหลังชุดทำงานของ{0}ขึ้นมาอย่างกะทันหัน",
"첫 월급을 받은 날, 한참 고르다 제일 싼 식당에서 제일 비싼 메뉴를 시켜 먹었다":"วันที่ได้เงินเดือนแรก เลือกอยู่นานแล้วสั่งเมนูที่แพงที่สุดในร้านที่ถูกที่สุดมากิน",
