"퇴근 후 {0}와/과 허름한 밥집에 앉아, 속에 담아 둔 말을 안주 삼아 풀어놓았다":"หลังเลิกงานนั่งที่ร้านข้าวโทรม ๆ กับ{0} เล่าเรื่องที่เก็บไว้ในใจเป็นกับแกล้ม",
"퇴근길 노점에서 김이 오르는 국수를 호호 불어 먹으며, 낯선 사람과 어깨를 나란히 했다":"ระหว่างทางกลับบ้านที่แผงข้างทาง เป่าก๋วยเตี๋ยวที่มีไอลอยแล้วกิน นั่งเคียงไหล่กับคนแปลกหน้า",
