"퇴근길 버스에서 이어폰을 꽂고 낯선 나라 말을 소리 없이 따라 읽다가, 처음으로 한 문장을 통째로 알아들었다":"บนรถเมล์ขากลับ เสียบหูฟังแล้วอ่านตามภาษาต่างประเทศโดยไม่ออกเสียง ได้ยินเข้าใจทั้งประโยคเป็นครั้งแรก",
"퇴근길 포장마차에서 김이 오르는 어묵 국물을 호호 불어 마시며, 낯선 사람과 어깨를 나란히 했다":"ระหว่างทางกลับบ้านที่ร้านรถเข็นข้างทาง เป่าน้ำซุปลูกชิ้นปลาที่มีไอลอยแล้วดื่ม นั่งเคียงไหล่กับคนแปลกหน้า",
"퇴근길 현관 앞에 얼룩 고양이가 앉아 있다":"แมวสามสีนั่งอยู่หน้าประตูบ้านตอนกลับจากทำงาน",
"퇴근길마다 반찬을 들고 들러 {0}의 안부만 확인하고 서둘러 나오는 날이 이어졌다":"ทุกวันขากลับถือกับข้าวแวะไปดูแค่ว่า{0}สบายดีไหมแล้วรีบกลับ เป็นแบบนี้ต่อเนื่องหลายวัน",
"퇴근하자마자 버스에서 내려 다른 일터로 갔고, 막차 시간에 맞춰 숨을 몰아쉬며 집에 들어갔다":"เลิกงานปุ๊บก็ลงรถเมล์ไปที่ทำงานอีกแห่ง ให้ทันเวลารถเที่ยวสุดท้าย หอบหายใจเข้าบ้าน",
