"하굣길 같은 방향으로 걷는 그 사람 뒤에서 말은 걸지 못하고 일부러 신발끈을 고치는 척하며 걸음을 늦췄다":"เดินไปทางเดียวกับคนนั้นตอนเลิกเรียน แต่ไม่กล้าทัก จึงแกล้งผูกเชือกรองเท้าเพื่อชะลอฝีเท้า",
"하굣길 담벼락에 기대 {0}에게 아무한테도 못 한 비밀을 털어놨고 해가 지도록 둘은 말이 없었다":"พิงกำแพงระหว่างทางกลับจากโรงเรียน เล่าความลับที่ไม่เคยบอกใครให้{0}ฟัง จนตะวันตกดินสองคนก็ไม่พูดอะไร",
"하굣길에 {0}이/가 눈치를 채고 놀려 대는 통에 귀까지 빨개진 채 모른 척하고 성큼성큼 앞서서 걸었다":"ระหว่างทางกลับจากโรงเรียน {0}จับสังเกตได้แล้วแซวไม่หยุด หูแดงไปหมด แต่แกล้งทำเป็นไม่รู้แล้วเดินนำหน้าไปก้าวยาว ๆ",
"하나뿐인 셔츠를 다려 입고 면접장에 서서, 이 일이 꼭 필요하다는 말을 두 번이나 되풀이했다":"รีดเสื้อเชิ้ตตัวเดียวที่มีใส่ ยืนอยู่ในห้องสัมภาษณ์ พูดซ้ำสองรอบว่าต้องการงานนี้จริง ๆ",
"하늘이 노랗게 물들 때까지 강둑에 누워 있었다. 들키지 않았다":"นอนอยู่บนคันริมแม่น้ำจนท้องฟ้าเปลี่ยนเป็นสีเหลือง ไม่มีใครจับได้",
