"하루 두 번 머리에 물동이를 이고 먼 샘터에서 집까지 걸었고 돌아오는 길엔 목이 타는데도 한 방울을 아꼈다":"วันละสองครั้งแบกโอ่งน้ำบนหัวเดินจากบ่อน้ำไกลมาถึงบ้าน ตอนกลับคอแห้งผากก็ยังประหยัดไว้ทุกหยด",
"하루 몇 시간만 일했다":"ทำงานแค่วันละไม่กี่ชั่วโมง",
"하루 종일 무거운 짐을 나르던 허리가 저녁에 끊어질 듯 아파, 파스를 붙이고 모로 누워 잠을 청했다":"แบกของหนักทั้งวัน ตกเย็นเอวปวดจะขาด แปะแผ่นแปะแก้ปวดแล้วนอนตะแคงพยายามหลับ",
"하루 한 갑이 반 갑이 되었다. 기침은 아침마다 여전히 찾아왔다":"หนึ่งซองต่อวันกลายเป็นครึ่งซอง แต่อาการไอก็ยังมาทุกเช้า",
"학교 급식으로 나온 김이 모락모락 나는 따뜻한 죽 한 그릇이 그날 하루의 가장 든든한 끼니였다":"ข้าวต้มอุ่น ๆ ถ้วยหนึ่งที่มีไอลอยจากอาหารกลางวันของโรงเรียน คือมื้อที่อิ่มใจที่สุดของวัน",
"학교 대신 집안일을 맡았다":"ต้องรับงานบ้านแทนการไปโรงเรียน",
"학교 대표로 뛴 첫 경기, {0}의 패스를 받아 골문 구석으로 찼다. 운동장이 터져 나갔다":"นัดแรกที่ลงแข่งเป็นตัวแทนโรงเรียน รับบอลจาก{0}แล้วเตะเข้ามุมประตู สนามแทบแตก",
"학교 대표로 뛴 첫 경기, 골문 구석으로 공이 빨려 들어갔다. 운동장이 터져 나갔다":"นัดแรกที่ลงแข่งเป็นตัวแทนโรงเรียน ลูกบอลพุ่งเข้ามุมประตู สนามแทบแตก",
