"학교 무대 조명 아래서 떨리는 손으로 연주를 마치자 객석의 {0}이/가 가장 크게 박수쳤다":"หลังเล่นดนตรีจบด้วยมือสั่นใต้แสงไฟเวทีโรงเรียน {0}ในที่นั่งผู้ชมปรบมือดังที่สุด",
"학교 사무실에 찾아가 분납을 청했다. 담당자가 서류 한 장을 내밀었다":"ไปที่ห้องธุรการของโรงเรียนแล้วขอผ่อนค่าเล่าเรียน เจ้าหน้าที่ยื่นเอกสารมาหนึ่งแผ่น",
"학교 첫날 이름표를 가슴에 달고 교문 안으로 들어가며 {0}을/를 몇 번이나 돌아보았다":"วันแรกที่โรงเรียน ติดป้ายชื่อที่อก เดินเข้าประตูโรงเรียน หันกลับไปมอง{0}หลายครั้ง",
"학교 축제 무대에 설 사람을 뽑는다":"กำลังคัดเลือกคนขึ้นเวทีงานเทศกาลโรงเรียน",
