"학교에 보낼 형편이 빠듯하다":"ฐานะทางบ้านตึงมือที่จะส่งเรียนหนังสือ",
"학교에서 돌아오면 가방을 던져 두고 {0}을/를 도와 설거지와 빨래부터 먼저 해치웠다":"พอกลับจากโรงเรียนก็โยนกระเป๋าทิ้งไว้ แล้วช่วย{0}ล้างจานกับซักผ้าก่อนเป็นอย่างแรก",
"학교에서는 또박또박, 집에 가는 버스에서는 편한 말로 돌아왔다":"ที่โรงเรียนพูดชัดถ้อยชัดคำ ส่วนบนรถเมล์กลับบ้านก็กลับมาพูดแบบสบาย ๆ",
"학비가 밀려 교실 밖에 서 있다 집으로 돌아왔고 {0}은/는 밤늦게까지 말이 없었다":"ค้างค่าเล่าเรียนจึงต้องยืนอยู่นอกห้องเรียนแล้วกลับบ้านมา {0}ไม่พูดอะไรจนดึก",
